def _trace_fields(parts: list[dict[str, str]]) -> dict[str, Any]:
    hidden, shown = split_trace(parts)
    frames = sum(part["kind"] == "frame" for part in hidden)
    chained = sum(part["kind"] == "chain" for part in hidden)
    label = ", ".join(
        text
        for count, text in [
            (frames, f"{frames} more frame{'s' if frames != 1 else ''}"),
            (chained, f"{chained} chained exception{'s' if chained != 1 else ''}"),
        ]
        if count
    )
    return {"trace": shown, "trace_hidden": hidden, "trace_more": label or "full traceback"}


# a repr shown in the chat is cut here (a cell shows all of it; the chat is kept in the state)
MAX_REPR_CHARS = 20_000


def _short_repr(value: Any) -> str:
    text = repr(value)
    return text if len(text) <= MAX_REPR_CHARS else f"{text[:MAX_REPR_CHARS]}… ({len(text):,} characters in all)"


def event(fn: Any) -> Any:
    """`rx.event` for this app's handlers: each run is also timed (perf.timed), for the debug
    panel's System tab. Background events keep plain `rx.event(background=True)`.
    """
    return rx.event(perf.timed(fn))


def _json_size(value: Any) -> int:
    """About how many bytes a state var is as JSON: what the server keeps and sends for it."""

    def plain(item: Any) -> Any:
        return dataclasses.asdict(item) if dataclasses.is_dataclass(item) and not isinstance(item, type) else str(item)

    try:
        return len(json.dumps(value, default=plain, ensure_ascii=False))
    except (TypeError, ValueError):
        return 0


