    def _session(self) -> Session:
        return get_session(self.router.session.client_token)

    def _log_context(self, origin: str, **where: str) -> Any:
        """Tag the log records of what runs inside with this tab's session and where it started
        (chat | form | view | cell). Follows asyncio tasks and asyncio.to_thread.

        where: what the debug log links back to (logs.target): turn='turn-<n>' for a chat
        turn, slot='tab:<name>' / 'cell:<id>' for a form, page or cell run.
        """
        session = logs.session_id(self.router.session.client_token)
        return logger.contextualize(session=session, origin=origin, **where)

    def _load_debug(self) -> None:
        mine = logs.session_id(self.router.session.client_token)
        # a focus is always this tab's: turn and cell ids repeat across sessions
        session = mine if self.debug_mine or self.debug_focus else ""
        name = self.debug_focus.removeprefix("tab:")
        made_by = self._session().tool_call_ids.get(name, "") if self.debug_focus.startswith("tab:") else ""
        found, self.debug_count = logs.rows(self.debug_shown, session, self.debug_focus, made_by)
        # a link only where its target is on this page: this session's records
        self.debug_rows = [
            LogRow(**row) if row["session"] == mine else LogRow(**row | {"target": "", "target_label": ""})
            for row in found
        ]
        self.debug_kinds = list(dict.fromkeys([*logs.LOG_FORMATS, *logs.kinds()]))
        self.debug_stats = logs.stats(self._session().namespace, BUILTIN_NAMES)

    def _refresh_debug(self) -> None:
        """After something finished: reload the debug panel if it is open."""
        if self.show_debug:
            self._load_debug()
            if self.debug_tab == "agents":
                self._load_agents()

    def _load_agents(self) -> None:
        """The Agents tab's live part: what this chat's model
        loaded and called (agents.activity).
        """
        self.agent_loaded, self.agent_calls = agents.activity(self._session().ai_history)

    def _sync(self, prefer: str = "") -> None:
        """Re-read the session's viewable values into the
        tab list and redraw the selected one.
        """
        with perf.span("sync tabs"):  # timed (the System tab): it makes a view of every variable
            self._sync_now(prefer)

    def _sync_now(self, prefer: str) -> None:
        session = self._session()
        everything, views = session.views(), session.tabs()
        self.objects = [
            {"name": name, "shape": view.summary, "source": session.sources.get(name, "python"), "kind": view.kind}
            for name, view in views.items()
        ]
        # forget what was done to tabs that are gone
        session.ui = {
            slot: ui
            for slot, ui in session.ui.items()
            if not (
                (slot.startswith("tab:") and slot[4:] not in views)
                or (slot.startswith("chat:") and slot[5:] not in everything)
            )
        }
        # ... and the tool calls behind names that are gone or bound to something else
        session.calls = {
            key: call
            for key, call in session.calls.items()
            if key.startswith("cell:") or session.namespace.get(key) is call.value
        }
        # results open inline in the chat follow their value
        # (a cell may have changed or deleted it)
        for name in {item.name for item in self.chat if item.open}:
            self._show(f"chat:{name}")
        if prefer in views:
            self._select(prefer)
        elif self.selected not in views:
            self._select(next(reversed(views), ""))
        self._show(f"tab:{self.selected}")
        self.mention_rows = [
            {**row, "parts": " ".join(part for part in row["parts"] if part.isidentifier())}
            for row in mentions.rows(session)
        ]
        # the last clear (a timer can end it while the pane is hidden)
        self.var_trash, self.var_can_undo = variables.trash_text(session), bool(session.trash)
        self.var_trash_seq = session.trash_seq
        if self._vars_on():
            self._sync_vars()

    def _sync_vars(self) -> None:
        """Re-read the Variables pane from the session (only while it is on screen)."""
        session = self._session()
        self.var_rows = variables.rows(session, self.var_show_all)
        names = [row["name"] for row in self.var_rows]
        self.var_summary = variables.summary(session, self.var_show_all)
        self.var_selected = [name for name in self.var_selected if name in names]
        self.var_open = self.var_open if self.var_open in names else ""
        self.var_detail = variables.detail(session, self.var_open) if self.var_open else []

    def _select(self, name: str) -> None:
        if name != self.selected:
            # a video in the tab being left stops; it is back, paused, with the tab
            if left := self._session().ui.get(f"tab:{self.selected}"):
                left.autoplay = False
            self.selected = name
            self.view = ViewData()

    def _show(self, slot: str) -> None:
        """Redraw the view shown at a slot (the selected
        tab, or a cell's result) from the session.
        """
        kind, _, key = slot.partition(":")
        if kind == "tab":
            if key == self.selected:
                self.view = self._session().show(slot)
        elif kind == "chat":
            view = self._session().show(slot, compact=True)
            for index, item in enumerate(self.chat):
                if item.kind == "ref" and item.name == key and item.open:
                    self.chat[index] = dataclasses.replace(item, view=view)
        elif (index := self._cell_index(key)) >= 0:
            self._update(index, view=self._session().show(slot, compact=True))
        else:
            # a printed "@" mention's result in the chat
            # (kind output): kept as a cell's result is
            view = self._session().show(slot, compact=True)
            for index, item in enumerate(self.chat):
                if item.kind == "output" and item.key == key:
                    self.chat[index] = dataclasses.replace(item, view=view)

    @rx.var
    def token(self) -> str:
        """The session id of this tab, passed to the editor
        so completions use the right namespace.
        """
        return self.router.session.client_token

    @rx.var
    def context_pct(self) -> int:
        """How full the context window is, 0-100 (0 when the window is unknown)."""
        return min(100, round(100 * self.context_tokens / self.context_max)) if self.context_max else 0

    @rx.var
    def context_size(self) -> str:
        """The meter's size, shown: '4%' (the token count when the window is unknown)."""
        return f"{self.context_pct}%" if self.context_max else tokens_text(self.context_tokens)

    @rx.var
    def context_tokens_text(self) -> str:
        """The meter's size, on hover (it replaces context_size): '43k / 1M tokens'."""
        if not self.context_max:
            return f"{tokens_text(self.context_tokens)} tokens"
        return f"{tokens_text(self.context_tokens)} / {tokens_text(self.context_max)} tokens"

    @rx.var
    def chat_on(self) -> bool:
        """Whether the chat pane is on screen: its toggle, unless a pane is zoomed."""
        return self.zoomed == "chat" or (self.zoomed == "" and self.show_chat)

    @rx.var
    def results_on(self) -> bool:
        return self.zoomed == "results" or (self.zoomed == "" and self.show_results)

    @rx.var
    def python_on(self) -> bool:
        return self.zoomed == "python" or (self.zoomed == "" and self.show_python)

    def _vars_on(self) -> bool:
        """Whether the Variables pane is on screen (for handlers:
        read after they change the layout).
        """
        return self.zoomed == "variables" or (self.zoomed == "" and self.show_variables)

    @rx.var
    def variables_on(self) -> bool:
        return self._vars_on()

    @rx.var
    def terminal_on(self) -> bool:
        return self.zoomed == "terminal" or (self.zoomed == "" and self.show_terminal)

    @rx.var
    def terminal_layout(self) -> str:
        """The Terminal pane, a strip under the bottom row (as VS Code's): hidden, alone (no
        bottom row, so it takes the height under the chat) or split (under the bottom row).
        """
        if not self.terminal_on:
            return "hidden"
        return "split" if self.bottom_on else "alone"

    @rx.var
    def pane_layout(self) -> str:
        """The results pane: hidden, alone (Python hidden,
        so it takes the width left) or split.
        """
        if not self.results_on:
            return "hidden"
        return "split" if self.python_on else "alone"

    @rx.var
    def variables_layout(self) -> str:
        """The Variables pane: hidden, alone (nothing beside it, so it takes the full width) or
        side (a column at the right of Results / Python).
        """
        if not self.variables_on:
            return "hidden"
        return "side" if self.results_on or self.python_on else "alone"

    @rx.var
    def bottom_on(self) -> bool:
        """Whether anything is shown below the chat."""
        return self.results_on or self.python_on or self.variables_on

    @rx.var
    def no_panels(self) -> bool:
        """Whether no panel is shown at all: the window is then the desktop (ui.desktop)."""
        return not (self.chat_on or self.bottom_on or self.terminal_on)

    @rx.var
    def var_selected_summary(self) -> str:
        """What the ticked rows hold together, eg 'selected
        2 · 81 KB' ("" when none is ticked).
        """
        sizes = [int(row["bytes"]) for row in self.var_rows if row["name"] in self.var_selected]
        return f"selected {len(sizes)} · {perf.size_text(sum(sizes))}" if sizes else ""

    @rx.var
    def var_all_selected(self) -> bool:
        return len(self.var_rows) > 0 and len(self.var_selected) == len(self.var_rows)

    @rx.var
    def chat_layout(self) -> str:
        """The chat pane: hidden, alone (nothing below it,
        so it takes the full height) or split.
        """
        if not self.chat_on:
            return "hidden"
        return "split" if self.bottom_on or self.terminal_on else "alone"

    @rx.var
    def chat_refs(self) -> list[str]:
        """Names of the results that have a tool-call row in the chat."""
        return [item.name for item in self.chat if item.kind == "ref"]

    @rx.var
    def has_objects(self) -> bool:
        return len(self.objects) > 0

    @event
    def on_load(self):
        # chat saved before ChatItem existed was plain dicts
        if any(isinstance(item, dict) for item in self.chat):
            self.chat = [ChatItem(**item) if isinstance(item, dict) else item for item in self.chat]
        self._sync()
        self._sync_usage()  # the context meter shows from the start (0 tokens)
        return State.load_spend_meters

    @event
    def select_object(self, name: str):
        self._open_tab(name)

    def _open_tab(self, name: str) -> None:
        self._reveal_results()
        if self._session().closed.pop(name, None) is not None:
            self._sync(prefer=name)  # a closed tab opens again
            return
        self._select(name)
        self._show(f"tab:{name}")

    # -- the Variables pane (variables.py) ----------------------------

    @event
    def show_var(self, name: str):
        """Click on a variable's name: open its Results tab (again, if closed) when it has a
        view, else unfold its details.
        """
        if name in self._session().views():
            self._open_tab(name)
            self._sync_vars()  # its tab is no longer closed
        else:
            self._open_var(name)

    @event
    def open_var(self, name: str):
        self._open_var(name)

    def _open_var(self, name: str) -> None:
        """Unfold a variable's details, or fold them if they are the ones open."""
        self.var_open = "" if self.var_open == name else name
        self.var_detail = variables.detail(self._session(), self.var_open) if self.var_open else []

    @event
    def toggle_var(self, name: str):
        """A row's checkbox."""
        if name in self.var_selected:
            self.var_selected = [other for other in self.var_selected if other != name]
        else:
            self.var_selected = [*self.var_selected, name]

    @event
    def toggle_all_vars(self):
        """The header's checkbox: select every listed variable, or none if all are."""
        names = [row["name"] for row in self.var_rows]
        self.var_selected = [] if len(self.var_selected) == len(names) else names

    @event
    def toggle_var_show_all(self):
        self.var_show_all = not self.var_show_all
        self._sync_vars()

    def _clear_vars(self, names: list[str]):
        """Clear variables (Session.clear) and start the timer that frees them for good."""
        session = self._session()
        if not session.clear(names):
            return None
        self.var_note = ""
        self.var_selected = []
        # a clear run from the palette shows the pane: its Undo is there
        if not self._vars_on():
            self.zoomed, self.show_variables = "", True
        self._sync()
        self._refresh_debug()
        return State.expire_trash(session.trash_seq)

    @event
    def clear_var(self, name: str):
        return self._clear_vars([name])

    @event
    def clear_selected_vars(self):
        return self._clear_vars(list(self.var_selected))

    @event
    def clear_all_vars(self):
        """Clear every listed variable (so not modules, functions
        and classes unless they are shown).
        """
        return self._clear_vars(variables.names(self._session(), self.var_show_all))

    @event
    def undo_clear_vars(self):
        skipped = self._session().restore()
        self.var_note = f"not put back, bound again since: {', '.join(skipped)}" if skipped else ""
        self._sync()

    def _purge_vars(self) -> None:
        """Drop the cleared batch for good (Session.purge)
        and blank the cell results that showed it.
        """
        for cell_id in self._session().purge():
            if (index := self._cell_index(cell_id)) >= 0:
                self._update(index, text="", view=ViewData())
            else:
                self._show(f"cell:{cell_id}")  # a printed mention's result in the chat: now gone
        self._sync()
        self._refresh_debug()

    @event
    def free_vars_now(self):
        self._purge_vars()

    @rx.event(background=True)  # plain: its wait is not a slow handler (see `event`)
    async def expire_trash(self, seq: int):
        """UNDO_SECONDS after a clear: free that batch, unless it was undone or another clear
        (which freed it) came since.
        """
        await asyncio.sleep(variables.UNDO_SECONDS)
        async with self:
            session = self._session()
            if session.trash and session.trash_seq == seq:
                self._purge_vars()

    # -- closing tabs (x, right-click menu) ---------------------------

    def _close(self, names: list[str]) -> None:
        """Close tabs. If the selected one goes, the tab to its
        right is selected (else the one to its left).
        """
        order = [obj["name"] for obj in self.objects]
        prefer = ""
        if self.selected in names and self.selected in order:
            at = order.index(self.selected)
            rest = [name for name in order[at + 1 :] + order[:at][::-1] if name not in names]
            prefer = rest[0] if rest else ""
        self._session().close_tabs(names)
        self.menu_tab = ""
        self._sync(prefer=prefer)

    @event
    def close_tab(self, name: str):
        self._close([name])

    @event
    def close_other_tabs(self, name: str):
        self._close([obj["name"] for obj in self.objects if obj["name"] != name])

    @event
    def close_tabs_right(self, name: str):
        order = [obj["name"] for obj in self.objects]
        if name in order:
            self._close(order[order.index(name) + 1 :])

    @event
    def close_all_tabs(self):
        self._close([obj["name"] for obj in self.objects])

    @event
    def open_tab_menu(self, name: str, info: dict[str, Any]):
        self.menu_tab = name
        self.menu_x, self.menu_y = int(info.get("client_x", 0)), int(info.get("client_y", 0))

    @event
    def close_menus(self):
        """Close the tab menu, the "+" menu and the help panel (click outside, Escape)."""
        self.menu_tab = ""
        self.add_menu = False
        self.palette = False
        self.show_help = False
        self.show_debug = False

    @event
    def show_in_chat(self, name: str):
        """Scroll the chat to the row of the tool call that returned a result, and flash it."""
        yield from self._reveal(f"ref-{name}")

    @event
    def reveal(self, target: str):
        """Go to a part of the page and flash it (see _reveal)."""
        yield from self._reveal(target)

    def _reveal(self, target: str):
        """The one way the app takes you somewhere: show the pane, scroll to it, flash it
        (assets/panes.js window.reveal, the same animation everywhere).

        target: a chat row's id ('ref-<name>', 'call-<tool_call_id>', 'turn-<n>'), a result's
        tab ('tab:<name>', opened again if it was closed) or a cell ('cell:<id>').
        """
        self.menu_tab, self.add_menu, self.show_help, self.show_debug = "", False, False, False
        kind, _, key = target.partition(":")
        if kind == "tab":
            if key not in self._session().views():
                return
            self._reveal_results()
            if self._session().closed.pop(key, None) is not None:
                self._sync(prefer=key)
            else:
                self._select(key)
                self._show(target)
            element = f"tab-{key}"
        elif kind == "cell":
            self.show_python = True
            if self.zoomed not in ("", "python"):
                self.zoomed = ""
            element = f"cell-{key}"
        else:
            self.show_chat = True
            if self.zoomed not in ("", "chat"):
                self.zoomed = ""
            element = target
        yield  # let the pane show before scrolling
        yield rx.call_script(f"window.reveal && window.reveal({json.dumps(element)})")

    @event
    def toggle_help(self):
        self.show_debug = False
        self.show_help = not self.show_help

    # -- debug panel (logs.py) ---------------------------------------------------

    @event
    def toggle_debug(self):
        self.show_help = False
        self.show_debug = not self.show_debug
        if self.show_debug:
            self.debug_focus = self.debug_focus_label = ""  # the icon / Alt+D opens everything
            # always on Requests: Logfire (the Spend tab) is only asked when that tab is
            # clicked or its Refresh pressed, never just by opening the panel
            self.debug_tab = "requests"
            self._load_debug()
        else:
            self.debug_rows = []  # nothing big kept in the tab's state while closed
            self.perf_memory = self.perf_variables = self.perf_sessions = self.perf_handlers = []
            self.perf_slowest = self.perf_calls = self.perf_state = self.perf_browser = []
            self.perf_text = ""

    @event
    def toggle_debug_full(self):
        """The debug panel: fill the window, or go back to the right-hand panel."""
        self.debug_full = not self.debug_full

    @event
    def show_logs(self, target: str):
        """Open the debug log on just the records of one thing: the reverse of a row's ↖ link.

        target: a tool call's chat row ('call-<id>'), an agent turn ('turn-<n>'), a result
        ('tab:<name>': the call that made it and its form runs) or a cell ('cell:<id>').
        """
        self.menu_tab, self.add_menu, self.show_help = "", False, False
        self.debug_focus, self.debug_focus_label = target, self._focus_label(target)
        self.show_debug, self.debug_tab = True, "requests"
        self._load_debug()

    def _focus_label(self, target: str) -> str:
        """What a focus is called at the top of the debug
        log, eg 'tool call get_player_usage'.
        """
        kind, _, key = target.partition(":")
        if kind == "tab":
            return f"result {key}: the call that made it and its form runs"
        if kind == "cell":
            index = self._cell_index(key)
            count = self.cells[index].count if index >= 0 else ""
            return f"cell [{count}]" if count else "this cell"
        item = next((item for item in self.chat if item.key == target), None)
        if target.startswith("call-"):
            return f"tool call {item.name}" if item else "tool call"
        text = item.text if item else ""
        return f"chat turn: {text[:60]}{'…' if len(text) > 60 else ''}"  # label length

    @event
    def clear_debug_focus(self):
        self.debug_focus = self.debug_focus_label = ""
        self._load_debug()

    def _sync_usage(self) -> None:
        """The title bar's context meter from the session: the
        chat's size and what the AI cost so far.
        """
        session = self._session()
        self.context_tokens = session.chat_tokens
        self.context_max = context_window() or 0
        self.chat_cost = cost_text(session.ai_cost)

    @event
    def refresh_usage(self):
        """After an inline chat (inline_edit.jsx clicks the hidden
        [data-usage-refresh] button): its cost.
        """
        self._sync_usage()

    @event
    def open_requests(self):
        """Open the debug panel on its Requests tab, everything
        shown (a chat turn's 'N requests' link).
        """
        self.menu_tab, self.add_menu, self.show_help = "", False, False
        self.debug_focus = self.debug_focus_label = ""
        self.show_debug, self.debug_tab = True, "requests"
        self._load_debug()

    @event
    def set_debug_tab(self, tab: str):
        self.debug_tab = tab
        if tab == "agents":
            self._load_agents()
        if tab == "spend":
            return State.load_spend
        if tab == "system":
            return State.load_perf
        return None

    @event
    def load_perf(self):
        """Read the System tab (perf.report), then ask the browser for its own numbers."""
        token = self.router.session.client_token
        sizes = {name: _json_size(getattr(self, name)) for name in type(self).base_vars if not name.startswith("perf_")}
        view = perf.report(self._session(), token, all_sessions(), logs.records(), sizes, BUILTIN_NAMES)
        self.perf_tiles, self.perf_memory, self.perf_variables = view.tiles, view.memory, view.variables
        self.perf_sessions, self.perf_handlers, self.perf_slowest = view.sessions, view.handlers, view.slowest
        self.perf_calls, self.perf_state, self.perf_process = view.calls, view.state, view.process
        self.perf_note, self.perf_text, self.perf_browser = view.note, view.text, []
        return rx.call_script("window.perfSnapshot ? window.perfSnapshot() : []", callback=State.set_browser_perf)

    @event
    def set_browser_perf(self, rows: list[dict[str, str]]):
        """The browser's side of the System tab, added to the report to copy."""
        self.perf_browser = [{"label": str(row.get("label", "")), "value": str(row.get("value", ""))} for row in rows]
        self.perf_text += "\n".join(perf.table_text("Browser", self.perf_browser, ("label", "value")))

    @event
    def clear_perf(self):
        """Forget the kept timings (every session's) and read the tab again."""
        perf.clear()
        return State.load_perf

    @rx.event(background=True)
    async def load_spend(self):
        """Query Logfire for the Spend tab (two queries,
        a second or so), off the event loop.
        """
        async with self:
            if self.spend_loading:
                return
            self.spend_loading = True
            log_context = self._log_context("debug panel")
        # its requests show in the Requests tab, tagged with this session
        with log_context:
            view = await asyncio.to_thread(spend.load)
        async with self:
            self.spend_loading = False
            self.spend_status, self.spend_error, self.spend_note = view.status, view.error, view.note
            self.spend_tiles, self.spend_bars = view.tiles, view.bars
            self.spend_axis, self.spend_limits = view.axis, view.limits
            self.spend_rows, self.spend_top = view.rows, view.top
            self.spend_project_url = view.project_url
            self.spend_gateway_url = view.gateway_url
            self.spend_balance_url = view.balance_url
            self._set_meters(view)

    def _set_meters(self, view: spend.SpendView) -> None:
        """The title bar's spend meters from a load; a failed one keeps the last meters."""
        if view.status == "ok":
            self.spend_meters, self.spend_as_of = view.meters, view.as_of
            return
        problem = view.error or "see the Spend tab"
        self.spend_meters = [
            m | {"title": f"{m['title'].split(' Last read failed:')[0]} Last read failed: {problem}"}
            for m in self.spend_meters
        ]

    @rx.event(background=True)
    async def load_spend_meters(self):
        """The title bar's spend meters, when the app opens: 1 Logfire query, its project
        info and the 3 limit lookups, off the event loop.
        """
        async with self:
            log_context = self._log_context("title bar")
        with log_context:
            view = await asyncio.to_thread(spend.load, spend.DAYS, top=False)
        async with self:
            self._set_meters(view)

    @event
    def open_spend(self):
        """A title-bar spend meter: the debug panel on its Spend tab (which loads it)."""
        self.menu_tab, self.add_menu, self.show_help = "", False, False
        self.show_debug, self.debug_tab = True, "spend"
        return State.load_spend

    @event
    def refresh_debug(self):
        self._load_debug()

    @event
    def clear_debug(self):
        """Forget the log: this session's records when "this session only" is on, else all."""
        logs.clear(logs.session_id(self.router.session.client_token) if self.debug_mine else "")
        self._load_debug()

    @event
    def toggle_debug_kind(self, kind: str):
        """A kind chip: show only the picked kinds; none picked shows all."""
        shown = self.debug_shown
        self.debug_shown = [k for k in shown if k != kind] if kind in shown else [*shown, kind]
        self._load_debug()

    @event
    def toggle_debug_mine(self):
        self.debug_mine = not self.debug_mine
        self._load_debug()

    @event
    def toggle_inline(self, name: str):
        """A tool result's row in the chat: show its view
        inline under the row, or fold it away.
        """
        for index, item in enumerate(self.chat):
            if item.kind == "ref" and item.name == name:
                opening = not item.open
                # folding unmounts the view (a playing video stops); opening reads it fresh
                self.chat[index] = dataclasses.replace(item, open=opening, view=ViewData())
                if opening:
                    self._show(f"chat:{name}")

    @event
    async def view_event(self, slot: str, action: str, arg: Any):
        """Every event of a rendered view (render.render_component), wherever it is placed.

        slot says which view ('tab:<name>', 'cell:<id>'). The change goes into that slot's Ui
        (render.apply_event) and the view is redrawn. Two fetch, so they are here: 'page' gets
        another page of a video search, 'form_run' runs the view's tool form (tool_forms.py);
        either puts the new result in the slot.
        """
        session = self._session()
        view = session.view_at(slot)
        if view is None:
            return
        ui = session.ui.setdefault(slot, Ui())
        if action == "form_run":
            inputs = dict(arg or {})
            # text in the form's "Ask AI" box: the AI fills
            # the inputs instead of the tool running
            ask = str(inputs.pop(ASK_FIELD, "") or "").strip()
            step = self._ask_ai(slot, view, ui, inputs, ask) if ask else self._run_form(slot, view, ui, inputs)
            async for update in step:
                yield update
            return
        # an event that changes what the tool is asked for, eg a usage view's Offline / Online
        if (inputs := rerun_inputs(view, action, arg)) is not None:
            async for update in self._run_form(slot, view, ui, inputs):
                yield update
            return
        if action == "close":
            self._close_view(slot)
            return
        if action == "navigate":
            # the Browser's address box: the same slot shows the new page, checked first (one
            # logged request, 0.5 s at most) so a site that refuses framing gets its card
            url = normalize(str(arg.get("url", "") if isinstance(arg, dict) else arg))
            ok, why = (None, "")
            if url:
                with self._log_context("view", slot=slot):
                    ok, why = await frameable(url)
            session.put(slot, WebPage(url=url, frameable=ok, why=why))
            if slot.startswith(("tab:", "chat:")):
                self._sync()  # the tab's label is the page's host
            else:
                self._show(slot)
            return
        if action == "db_save":
            name = arg.get("var_name", "") if isinstance(arg, dict) else arg  # the Save as form
            self._save_query_result(slot, view, ui, str(name or "").strip())
            return
        if action in ("db_run", "db_open"):
            async for update in self._run_query(slot, view, ui, action, str(arg)):
                yield update
            return
        if action == "form_reset":
            if session.restore_original(slot):
                self._new_result(slot, ui)
            return
        if action != "page":
            apply_event(view, ui, action, arg)
            self._show(slot)
            return
        current = view.value
        if ui.paging or not isinstance(current, MatchVideos) or not 1 <= current.page + arg <= current.pages:
            return
        ui.paging, ui.error = True, ""
        self._show(slot)
        yield
        try:
            with self._log_context("view", slot=slot):
                page = await asyncio.to_thread(search_videos, **current.query.model_dump(), page=current.page + arg)
        except Exception as error:  # noqa: BLE001  # network / site errors are shown in the view
            ui.error = f"Couldn't load that page: {error}"
        else:
            session.put(slot, page)
        ui.paging = False
        if slot.startswith(("tab:", "chat:")):
            self._sync()  # the tab's label changes with the page (and it redraws chat slots)
        else:
            self._show(slot)
        self._refresh_debug()

    async def _run_form(self, slot: str, view: Any, ui: Ui, inputs: dict[str, Any]):
        """Run a view's tool with the form's inputs; the
        result replaces the value at the slot.
        """
        form = form_for(view.value)
        if form is None or ui.running or ui.ai_busy:
            return
        ui.running, ui.error = True, ""
        self._show(slot)
        yield
        session = self._session()
        try:
            with self._log_context("form", slot=slot):
                result, used = await asyncio.to_thread(form.run, inputs)
        except Exception as error:  # noqa: BLE001  # bad input / site errors are shown in the view
            ui.error = f"{form.title}: {error}"
        else:
            session.put(slot, result, inputs=used)
            # a proposal that ran is the result's inputs now; a failed run keeps it to correct
            drop_proposal(ui)
        ui.running = False
        self._new_result(slot, ui, replaced=not ui.error)
        self._refresh_debug()

    async def _ask_ai(self, slot: str, view: Any, ui: Ui, inputs: dict[str, Any], instruction: str):
        """A form's inline chat (inline_fill.py): the AI turns the instruction into the form's
        inputs, shown in the form as a proposal (Ui.proposed). Nothing runs: the user does
        that. inputs: the form as submitted, so what is on screen (typed by hand, or the last
        proposal) is what the AI changes.
        """
        form = form_for(view.value)
        if form is None or ui.running or ui.ai_busy:
            return
        ui.ai_open = ui.form_open = ui.ai_busy = True
        ui.ai_error = ""
        self._show(slot)
        yield
        session = self._session()
        with self._log_context("inline fill", slot=slot):
            answer = await fill_inputs(session, form, inputs, instruction, note=view.note or view.summary)
        ui.ai_busy = False
        if answer.error:
            ui.ai_error, ui.ai_note = answer.error, answer.usage
        else:
            call = session.call_at(slot, view.value)
            before = form.texts(
                view.value.inputs if isinstance(view.value, ToolRequest) else call.inputs if call else {}
            )
            changed = sum(answer.inputs.get(name, "") != was for name, was in before.items())
            ui.proposed, ui.proposals = answer.inputs, ui.proposals + 1
            ui.ai_note = " · ".join(
                filter(None, [f"{changed} changed" if changed else "nothing to change", answer.usage])
            )
        self._show(slot)
        self._sync_usage()
        self._refresh_debug()

    def _save_query_result(self, slot: str, view: Any, ui: Ui, name: str) -> None:
        """A SmashDb console's Save as: bind its query's result to `name` in Python (it gets a
        tab, as any DataFrame bound to a name), staying in the console.
        """
        console = view.value
        if not isinstance(console, DbConsole) or console.df is None:
            return
        session = self._session()
        _, _, own = slot.partition(":")
        if problem := session.name_problem(name, keep=own):
            ui.save_error, ui.save_note = problem, ""
            self._show(slot)
            return
        session.namespace[name] = console.df
        session.sources[name] = "SmashDb console"
        session.closed.pop(name, None)
        # the grid's filter / sort / SQL on self are views of the result, not part of it
        extras = [part for part, on in [("row filter", ui.query), ("sort", ui.sort_col), ("SQL ▸", ui.sql)] if on]
        without = f"; the query's result, without the {' / '.join(extras)}" if extras else ""
        ui.save_note = f"saved as {name} ({console.df.height} × {console.df.width}{without})"
        ui.save_error, ui.saves = "", ui.saves + 1
        self._sync()

    async def _run_query(self, slot: str, view: Any, ui: Ui, action: str, arg: str):
        """Run a SmashDb console's query; the console with the result replaces the one at the
        slot. db_run: arg is the SQL ("" = the editor's text, for the Run button). db_open: arg
        is a table, shown whole (and written in the editor). A failed query leaves the last
        result and shows its traceback, as a Python cell would.
        """
        console = view.value
        if not isinstance(console, DbConsole) or ui.running:
            return
        if action == "db_open":
            sql = f'select * from "{arg}"'
            ui.draft, ui.db_resets = sql, ui.db_resets + 1
        else:
            sql = arg or ui.draft or console.sql
        if not clean_sql(sql):
            return
        ui.running = True
        self._show(slot)
        yield
        try:
            result = await asyncio.to_thread(console.run, sql)
        except Exception as error:  # noqa: BLE001  # any bad query is shown in the view
            parts = trace_parts(error, error.__traceback__)
            ui.trace = {**_trace_fields(parts), "text": "".join(traceback.format_exception(error))}
        else:
            # a new table: what was done to the old one (its SQL on self, sort, filter) is gone
            ui.trace, ui.sql, ui.sort_col, ui.descending, ui.query = {}, "", "", False, ""
            ui.sql_resets += 1
            self._session().put(slot, result)
        ui.running = False
        if slot.startswith(("tab:", "chat:")):
            self._sync()  # the tab's label changes with the result
        else:
            self._show(slot)

    def _new_result(self, slot: str, ui: Ui, replaced: bool = True) -> None:
        """Redraw a slot after its tool form ran (or was reset);
        replaced = it holds another result.
        """
        if replaced:
            # its own inputs in the form, no video picked
            ui.runs += 1
            ui.error = ""
            ui.playing, ui.list_hidden, ui.autoplay = {}, False, False
        if slot.startswith(("tab:", "chat:")):
            self._sync()  # the tab's label changes (and it redraws chat slots)
        else:
            self._show(slot)

    @event
    def open_add_menu(self, info: dict[str, Any]):
        """The Results tab bar's "+": a menu of the widgets
        that can be added by hand, at the pointer.
        """
        self.menu_tab = ""
        self.add_menu, self.palette = True, False
        self.menu_x, self.menu_y = int(info.get("client_x", 0)), int(info.get("client_y", 0))

    @event
    def close_palette(self):
        """Close the palette only: it sits on top of everything, so what is under it (the debug
        log, help) stays (running a command, a click outside it, Escape).
        """
        self.palette = False

    @event
    def toggle_palette(self):
        """Shortcut.PALETTE: the command palette, in the middle of the window."""
        self.menu_tab = ""
        self.add_menu, self.palette = False, not self.palette

    @event
    def add_widget(self, kind: str):
        """Add a widget by hand, as a new tab: a tool form to fill in and run (a ToolRequest
        until its first run), or the widget's own blank value (eg a SmashDb console).
        """
        self._add_widget(kind)

    def _add_widget(self, kind: str, in_chat: bool = False) -> str:
        """Add the widget as a new tab; returns the name it is bound to ("" if it can't be
        added). in_chat: also show it unfolded in the chat, under the slash command that added
        it (as a tool's result is), and leave the panes
        as they are instead of bringing up Results.
        """
        self.add_menu = self.palette = False
        widget = widget_of(kind)
        session = self._session()
        value = widget.blank(session) if widget and widget.addable else None
        if value is None:
            return ""
        name = session.bind_result(value, source=widget.form.key if widget.form else widget.kind)
        session.ui[f"tab:{name}"] = Ui(form_open=True)
        if in_chat:
            session.ui[f"chat:{name}"] = Ui(form_open=True)
            self.chat.append(ChatItem(kind="ref", name=name, text=widget.title, open=True))
        else:
            self._reveal_results()
        self._sync(prefer=name)
        return name

    @event
    async def add_widget_ask(self, kind: str, ask: str):
        """A widget's slash command, eg "/vods" or "/vods mkleo vs sparg0": add the widget and
        show it in the chat, under the command's row. With text (ask), the inline AI then fills
        its inputs from it there (as its "Ask AI" row does). Nothing runs: the inputs are a
        proposal, the user runs them.
        """
        name = self._add_widget(kind, in_chat=True)
        if not name or not ask:
            return
        yield
        slot = f"chat:{name}"
        session = self._session()
        view = session.view_at(slot)
        if view is None:
            return
        async for update in self._ask_ai(slot, view, session.ui.setdefault(slot, Ui()), {}, ask):
            yield update

    @event
    def browse(self, form: dict[str, Any]):
        """A link clicked anywhere (assets/panes.js submits the hidden browse form): the page
        in the one `web` Browser tab, which panes.js then floats over the app (a glance, as in
        Zen). The layout before it is kept, so closing the glance (close_glance) puts it back.
        """
        url = normalize(str(form.get("url", "")))
        if not url:
            return
        session = self._session()
        if not self.glance_from:
            self.glance_from = {
                "show_results": "1" if self.show_results else "",
                "zoomed": self.zoomed,
                "selected": self.selected,
            }
        session.closed.pop(WEB_TAB, None)  # a closed `web` tab opens again
        # panes.js already asked (a refused link opened in a real tab): "true", or "" (unknown)
        session.namespace[WEB_TAB] = WebPage(url=url, frameable=True if form.get("frameable") == "true" else None)
        session.sources[WEB_TAB] = "browser"
        session.ui.setdefault(f"tab:{WEB_TAB}", Ui())
        self._reveal_results()
        self._sync(prefer=WEB_TAB)

    def _close_view(self, slot: str) -> None:
        """A view's × (render.close_view_button), as fits where it is shown: a Results tab
        closes (a glance closes as Esc would), a chat row folds, a cell's output is hidden.
        """
        kind, _, key = slot.partition(":")
        if kind == "tab" and key == WEB_TAB and self.glance_from:
            self._close_glance()
        elif kind == "tab":
            self._close([key])
        elif kind == "chat":
            for index, item in enumerate(self.chat):
                if item.kind == "ref" and item.name == key and item.open:
                    self.chat[index] = dataclasses.replace(item, open=False, view=ViewData())
        elif kind == "cell":
            session = self._session()
            session.outputs.pop(key, None)
            session.ui.pop(slot, None)
            if (index := self._cell_index(key)) >= 0:
                self._update(index, view=ViewData())

    @event
    def close_glance(self):
        """Esc or a click outside a glance (panes.js): close the `web` tab and put the layout
        back as it was before the link was clicked. Its dock button keeps it instead
        (dock_glance).
        """
        self._close_glance()

    def _close_glance(self) -> None:
        before, self.glance_from = self.glance_from, {}
        if not before:
            return
        self._session().close_tabs([WEB_TAB])
        self.show_results, self.zoomed = bool(before["show_results"]), before["zoomed"]
        self._sync(prefer=before["selected"])

    @event
    def dock_glance(self):
        """The glance's dock (float) button: it stays as the `web` tab in Results."""
        self.glance_from = {}

    def _reveal_results(self) -> None:
        """Make sure the results pane is on screen (eg
        a video was opened from a zoomed cell).
        """
        self.show_results = True
        if self.zoomed != "results":
            self.zoomed = ""

    @event
    def toggle_zoom(self, pane: str):
        """Fill the window with one pane, or go back to the
        normal layout (button, Shortcut.FULL_SCREEN).
        """
        self.zoomed = "" if self.zoomed == pane else pane
        self._start_terminal()
        if self._vars_on():
            self._sync_vars()

    def _start_terminal(self) -> None:
        """The Terminal pane's shell starts the first time it shows (terminal_started)."""
        if self.zoomed == "terminal" or (self.zoomed == "" and self.show_terminal):
            self.terminal_started = True

    @event
    def toggle_pane(self, pane: str):
        """Bottom bar: show or hide a pane (PANES)."""
        name = f"show_{pane}"
        if pane not in PANES:
            return
        if self.zoomed:
            # leaving full screen: the clicked pane is the
            # one wanted back, so make sure it shows
            self.zoomed = ""
            setattr(self, name, True)
        else:
            setattr(self, name, not getattr(self, name))
        self._start_terminal()
        if self._vars_on():
            self._sync_vars()  # not kept current while hidden

    @event
    def hide_pane(self, pane: str):
        """A panel's close button: hide it, as its bottom-bar toggle does. Closing the panel
        that fills the window (zoomed) also goes back to the normal layout, without it.
        """
        if pane not in PANES:
            return
        setattr(self, f"show_{pane}", False)
        if self.zoomed == pane:
            self.zoomed = ""
        if self._vars_on():
            self._sync_vars()

    @event
    def toggle_python_variables(self):
        """Shortcut.TOGGLE_PYTHON_VARIABLES: the Python and Variables panes as a pair. Both on
        screen: hide both. Otherwise show both (so with one open, the other opens).
        """
        both = self.zoomed == "" and self.show_python and self.show_variables
        self.zoomed = ""  # as the bottom bar's toggles: leaving full screen for the panes asked for
        self.show_python = self.show_variables = not both
        if self._vars_on():
            self._sync_vars()  # not kept current while hidden

    def _new_cell(self) -> Cell:
        self.cell_seq += 1
        return Cell(id=f"c{self.cell_seq}")

    def _cell_index(self, cell_id: str) -> int:
        return next((i for i, cell in enumerate(self.cells) if cell.id == cell_id), -1)

    def _update(self, index: int, **changes: Any) -> None:
        # Replace the item rather than mutating it, so Reflex always sees the change.
        self.cells[index] = dataclasses.replace(self.cells[index], **changes)

    async def _run(self, index: int, code: str) -> None:
        """Run one cell's code in the session and store its output on the cell."""
        session = self._session()
        cell_id = self.cells[index].id
        before = set(session.tabs())
        # exec blocks, so keep it off the event loop
        with self._log_context("cell", slot=f"cell:{cell_id}"):
            result = await asyncio.to_thread(session.run_python, code, f"In [{self.exec_count + 1}]")
        self.exec_count += 1
        if result.view is None:
            session.outputs.pop(cell_id, None)
        else:
            session.outputs[cell_id] = result.view
        session.ui.pop(f"cell:{cell_id}", None)  # a new result starts fresh
        self._update(
            index,
            code=code,
            count=str(self.exec_count),
            stdout=result.stdout.rstrip(),
            text=result.result_repr.rstrip(),
            error=result.error.rstrip(),
            **_trace_fields(result.trace),
            view=session.show(f"cell:{cell_id}", compact=True),
        )
        # a new name, or a closed tab's name bound to something new
        new = [name for name in session.tabs() if name not in before]
        self._sync(prefer=new[-1] if new else "")
        self._refresh_debug()

    async def _start(self, index: int, code: str):
        self.running = True
        self._update(index, count="*")
        yield
        await self._run(index, code)
        self.running = False

    @event
    async def run_cell(self, cell_id: str, code: str, advance: bool):
        """Run a cell with the editor's current text. advance (Shortcut.RUN_AND_ADVANCE)
        on the last cell appends a new one.
        """
        index = self._cell_index(cell_id)
        if index < 0 or self.running:
            return
        self._update(index, code=code)
        if advance and index == len(self.cells) - 1:
            self.cells.append(self._new_cell())
        if not code.strip():
            return
        async for update in self._start(index, code):
            yield update

    @event
    async def run_saved(self, cell_id: str):
        """Run button: the click blurs the editor first,
        so the cell's saved text is current.
        """
        index = self._cell_index(cell_id)
        if index < 0 or self.running or not self.cells[index].code.strip():
            return
        async for update in self._start(index, self.cells[index].code):
            yield update

    @event
    async def run_all(self):
        if self.running:
            return
        self.running = True
        for index in range(len(self.cells)):
            code = self.cells[index].code
            if not code.strip():
                continue
            self._update(index, count="*")
            yield
            await self._run(index, code)
            yield
        self.running = False

    @event
    def open_output(self, cell_id: str):
        """Bind a cell's result to a name (out<n>) so it also gets a tab."""
        index = self._cell_index(cell_id)
        session = self._session()
        view = session.outputs.get(cell_id)
        if index < 0 or view is None:
            return
        name = f"out{self.cells[index].count}"
        session.namespace[name] = view.value
        session.closed.pop(name, None)
        session.sources[name] = f"cell [{self.cells[index].count}]"
        self._sync(prefer=name)

    @event
    def save_code(self, cell_id: str, code: str):
        """Keep an edited-but-not-run cell's text (sent when the cell loses focus)."""
        index = self._cell_index(cell_id)
        if index >= 0:
            self._update(index, code=code)

    @event
    def add_cell(self):
        self.cells.append(self._new_cell())

    @event
    def add_cell_below(self, cell_id: str):
        """Shortcut.CELL_BELOW: a new cell right under this one (at the end if it is gone)."""
        index = self._cell_index(cell_id)
        self.cells.insert(index + 1 if index >= 0 else len(self.cells), self._new_cell())

    @event
    def delete_cell(self, cell_id: str):
        index = self._cell_index(cell_id)
        if index >= 0 and not self.running:
            del self.cells[index]
            self._session().outputs.pop(cell_id, None)
            self._session().ui.pop(f"cell:{cell_id}", None)
        if not self.cells:
            self.cells.append(self._new_cell())

    @event
    def clear_outputs(self):
        self._session().outputs.clear()
        for index in range(len(self.cells)):
            self._update(index, stdout="", text="", error="", **_trace_fields([]), view=ViewData())

    @event
    def submit_chat(self, form: dict[str, Any]):
        """The chat box's Send. A message starting with "/" is a slash command (commands.py):
        it runs what its palette row runs and is never
        sent to the agent. Anything else is a turn.

        A command that ran shows in the chat as a tool call does: a row with the command, what
        followed it and what it did, and, for one that adds a widget, the widget under it.
        """
        prompt = str(form.get("prompt", "")).strip()
        parsed = parse_slash(prompt)
        session = self._session()
        # a method call in an "@" mention that is refused or failed (mentions.problems):
        # nothing is sent or run, and the message goes back in the box to fix
        if problem := mentions.problems(prompt if parsed is None else parsed[1], session):
            self.chat.append(
                ChatItem(
                    kind="mention",
                    name="not sent",
                    text="a method call in an @ mention can't be used: fix it in the box",
                    key=f"mention-{len(self.chat)}",
                    detail=problem,
                    open=True,
                )
            )
            return rx.call_script(f"window.restoreChatBox && window.restoreChatBox({json.dumps(prompt)})")
        if parsed is None:
            # only "@" mentions of variables (mentions.py): print them, no turn
            if mentions.bare(prompt, session) is not None:
                return State.show_mentions(prompt)
            return State.send_chat(form)
        name, rest = parsed
        command = SLASH.get(name)
        known = ", ".join(f"/{other}" for other in SLASH)
        if command is None:
            self.chat.append(ChatItem(kind="note", text=f"/{name} isn't a command. There are: {known}"))
            return None
        if rest and not command.takes:
            # running anyway could clear things on a sentence that only began with the command
            self.chat.append(ChatItem(kind="note", name=f"/{name}", text="takes no text after it: not run"))
            return None
        row = State.slash_ran(f"/{name}", " · ".join(filter(None, [rest, self._slash_outcome(command)])))
        if command.slash_event:
            handler, *args = command.slash_event
            return [row, getattr(State, handler)(*args, rest)]
        if command.press:
            return [row, rx.call_script(f"window.smashPress({json.dumps(command.keys)})")]
        handler, *args = command.event
        run = getattr(State, handler)(*args) if args else getattr(State, handler)
        # clearing the chat takes its rows: the command's row comes after, in the new chat
        return [run, row] if handler == "clear_chat" else [row, run]

    def _slash_outcome(self, command: Any) -> str:
        """What a slash command is about to do, for its row in the chat: what it changes where
        that is known (how many variables go, a pane shown or hidden), else what it is.
        """
        handler = command.event[0] if command.event else ""
        if handler == "clear_all_vars":
            count = len(variables.names(self._session(), self.var_show_all))
            return f"cleared {count} variable{'s' if count != 1 else ''}" if count else "no variables to clear"
        if handler == "clear_chat":
            return "cleared: a new conversation"
        if handler == "assign_ask":
            return "the AI writes the code, you run it"
        if handler == "close_all_tabs":
            return f"closed {len(self.objects)} tab{'s' if len(self.objects) != 1 else ''}"
        if command.shown:
            return f"{command.title}: {'hidden' if getattr(self, command.shown) else 'shown'}"
        return f"{command.group}: {command.title}"

    @event
    def show_mentions(self, text: str):
        """A message that is only "@" mentions, eg "@q1" (mentions.bare): print each variable
        in the chat, with no AI call. A name with a view shows as a result does, unfolded under
        the message's row; a part of one ("@q1.char") or a value with no view shows as text.
        These rows are the app's: the agent never gets them (as a slash command's).
        """
        session = self._session()
        for mention in mentions.bare(text, session) or []:
            self.chat += self._printed(mention, "printed, not sent to the AI")
        self._sync()

    def _printed(self, mention: mentions.Mention, note: str) -> list[ChatItem]:
        """A mention printed in the chat, as rows to add: its "@name · type · shape · note"
        row, then the value, shown as the Python console shows the result of a cell holding the
        same text without the "@". A variable with a view shows as a result does, unfolded (its
        own row is what folds). A part of one or a call's result with a view ("@q1.describe()")
        shows as a cell's result: the same grid, with "open as tab". Anything else is its repr,
        under the row, whose caret folds it.
        """
        session = self._session()
        views = session.views()
        # its type is shown first (type_parts), then this
        about = " · ".join(filter(None, [perf.shape_text(mention.value), note]))
        typed = type_parts(mention.value)
        row = ChatItem(
            kind="mention", name=f"@{mention.path}", text=about, type_parts=typed, key=f"mention-{len(self.chat)}"
        )
        if mention.path in views:
            session.ui.setdefault(f"chat:{mention.path}", Ui())
            # the block's line: its type (type_parts), where it came from, its size
            label = " · ".join(filter(None, [session.sources.get(mention.path, ""), views[mention.path].summary]))
            return [row, ChatItem(kind="ref", name=mention.path, text=label, type_parts=typed, open=True)]
        view = to_view(mention.value)
        if view is None:
            # no view: its repr, as under a cell
            return [dataclasses.replace(row, detail=_short_repr(mention.value), open=True)]
        # kept where a cell's result is (Session.outputs), under an id of its own
        self.output_seq += 1
        key = f"m{self.output_seq}"
        session.outputs[key] = view
        shown = session.show(f"cell:{key}", compact=True)
        return [row, ChatItem(kind="output", key=key, name=f"@{mention.path}", view=shown)]

    @event
    def open_chat_output(self, key: str):
        """Open as tab, on a printed mention's result: bind it to the next free out<n>, as a
        cell's result is (open_output), so it gets a tab and a name to mention.
        """
        session = self._session()
        view = session.outputs.get(key)
        item = next((item for item in self.chat if item.kind == "output" and item.key == key), None)
        if view is None or item is None:
            return
        name = session.next_free_name("out")
        session.namespace[name] = view.value
        session.closed.pop(name, None)
        session.sources[name] = item.name
        self._reveal_results()
        self._sync(prefer=name)

    def chat_outputs(self) -> list[ChatItem]:
        return [item for item in self.chat if item.kind == "output"]

    def _chat_index(self, key: str) -> int:
        return next((index for index, item in enumerate(self.chat) if item.key == key), -1)

    @event
    async def assign_ask(self, text: str):
        """Run `/assign [name =] <what it should hold>` (assign.py): the AI writes the Python
        that makes a new variable, shown in the chat as code to review. Nothing runs here:
        assign_run does, when the user presses Enter on it.
        """
        if not text.strip():
            usage = "Say what the variable should hold, eg: /assign top5 = the five best players in @q1"
            self.chat.append(ChatItem(kind="note", name="/assign", text=usage))
            return
        key = f"assign-{len(self.chat)}"
        self.chat.append(ChatItem(kind="assign", key=key, status="asking"))
        yield
        session = self._session()
        with self._log_context("inline assign"):
            answer = await assign.propose(session, self.router.session.client_token, text)
        index = self._chat_index(key)
        if index < 0:  # the chat was cleared meanwhile
            return
        if answer.error:
            detail = " · ".join(filter(None, [answer.error, answer.usage]))
            self.chat[index] = dataclasses.replace(self.chat[index], status="failed", detail=detail)
        else:
            detail = " · ".join(filter(None, [assign.BASIS_TEXT.get(answer.basis, ""), answer.usage]))
            self.chat[index] = dataclasses.replace(
                self.chat[index], status="proposed", name=answer.name, text=answer.code, detail=detail
            )
        self._sync_usage()
        self._refresh_debug()

    @event
    async def assign_run(self, form: dict[str, Any]):
        """Enter (or Run) on a "/assign" proposal: run its code, as the user left it, and bind
        the variable it makes when its value is allowed (assign.run). The value then shows
        under the code, as a printed variable does. A failure
        stays in the box, to fix and run again.
        """
        index = self._chat_index(str(form.get("key", "")))
        code = str(form.get("code", "")).strip()
        if index < 0 or self.chat[index].status != "proposed" or not code:
            return
        if self.chat[index].name.startswith(SCRIPT_PREFIX):  # a "/script" proposal: Enter saves it
            self._script_save(index, code)
            return
        session = self._session()
        # shown as running before the run (from_url's browser can take 30 s): the box is
        # replaced by the code and a progress line, so a second Enter or click runs nothing
        self.chat[index] = dataclasses.replace(
            self.chat[index], status="running", text=code, error="", **_trace_fields([])
        )
        yield
        ran = await asyncio.to_thread(assign.run, session, code)
        item = dataclasses.replace(self.chat[index], status="proposed")
        # what each from_url in the code did, as a folded row: its summary, then (unfolded)
        # every browser step and parser the AI ran. The
        # requests themselves are in the debug log.
        fetched = [
            ChatItem(
                kind="mention",
                name="from_url",
                text=report.summary() + (" · /script saves it as a script" if report.savable else ""),
                detail=report.detail(),
                key=f"fetch-{len(self.chat)}-{n}",
            )
            for n, report in enumerate(ran.fetched)
        ]
        # each saved script the code called (ds.ai.scripts),
        # before what a failed one fell back to
        called = [
            ChatItem(kind="mention", name="script", text=made.summary(), key=f"script-{len(self.chat)}-{n}")
            for n, made in enumerate(ran.script_runs)
        ]
        fetched = [*called, *fetched]
        # a run again replaces the rows of the run before, instead of piling up under the box
        while index + 1 < len(self.chat) and self.chat[index + 1].key.startswith(("fetch-", "script-")):
            del self.chat[index + 1]
        # the last browser run that can become a script, for "/script" (with the code that
        # defined its model class, and the variable holding its rows)
        if savable := [report for report in ran.fetched if report.savable]:
            session.last_fetch = (savable[-1], code, ran.name)
        if not ran.name:
            self.chat[index] = dataclasses.replace(item, text=code, error=ran.error, **_trace_fields(ran.trace))
            self.chat[index + 1 : index + 1] = fetched
            self._refresh_debug()
            return
        mention = mentions.Mention(ran.name, session.namespace[ran.name])
        notes = [
            "replaced the old one" if ran.replaced else "",
            f"class {', '.join(ran.classes)} defined" if ran.classes else "",
        ]
        self.chat[index] = dataclasses.replace(
            item, status="done", name=ran.name, text=code, error="", **_trace_fields([])
        )
        printed = self._printed(mention, " · ".join(filter(None, ["assigned", *notes])))
        self.chat[index + 1 : index + 1] = [*fetched, *printed]
        self._sync()
        if fetched:
            self._refresh_debug()

    @event
    async def script_ask(self, text: str):
        """Run `/script [name]`: the AI writes a saved script (ds.ai.scripts) from the last
        from_url browser run, checked by running it with no AI, and shown as code to review;
        Enter saves it (assign_run). `/script list` lists the saved ones, `/script delete <id>`
        deletes one.
        """
        words = text.split()
        if words[:1] == ["list"]:
            rows = [f"{info.id}: {info.description or 'BROKEN: ' + info.problem}" for info in scripts.registry()]
            self.chat.append(ChatItem(kind="note", name="/script", text="; ".join(rows) or "no saved scripts yet"))
            return
        if words[:1] == ["delete"]:
            done = len(words) > 1 and scripts.delete(words[1])
            what = f"deleted {words[1]}" if done else "no such script: /script list shows them"
            self.chat.append(ChatItem(kind="note", name="/script", text=what))
            return
        session = self._session()
        if session.last_fetch is None:
            usage = "saves the last from_url run that used the browser as a script: there is none in this session"
            self.chat.append(ChatItem(kind="note", name="/script", text=usage))
            return
        report, code, name = session.last_fetch
        key = f"assign-{len(self.chat)}"
        self.chat.append(ChatItem(kind="assign", key=key, status="asking"))
        yield
        held = session.namespace.get(name)
        with self._log_context("script draft"):
            drafted = await scripts.draft(report, code, held if isinstance(held, list) else None, " ".join(words))
        session.ai_cost += drafted.cost
        index = self._chat_index(key)
        if index < 0:  # the chat was cleared meanwhile
            return
        if drafted.error:
            detail = " · ".join([drafted.error, *drafted.tried])
            self.chat[index] = dataclasses.replace(self.chat[index], status="failed", detail=detail)
        else:
            path = f"pkgs/ds/ai/temp/scripts/{drafted.id}.py"
            kind = f"changes the saved script {drafted.id}" if drafted.replaces else "a new saved script"
            detail = " · ".join([kind, drafted.verified, f"Enter saves {path}"])
            self.chat[index] = dataclasses.replace(
                self.chat[index], status="proposed", name=SCRIPT_PREFIX + drafted.id, text=drafted.code, detail=detail
            )
        self._sync_usage()
        self._refresh_debug()

    def _script_save(self, index: int, code: str) -> None:
        """Enter on a "/script" proposal: save its code, as the user left it, when it keeps the
        script rules (else why shows under the box, which stays). Past the size cap, ask which
        scripts to delete.
        """
        item = self.chat[index]
        script_id = item.name.removeprefix(SCRIPT_PREFIX)
        try:
            scripts.save(script_id, code)
        except ValueError as error:
            self.chat[index] = dataclasses.replace(item, text=code, error=str(error))
            return
        self._session().last_fetch = None
        self.chat[index] = dataclasses.replace(item, status="done", text=code, error="")
        path = f"pkgs/ds/ai/temp/scripts/{script_id}.py"
        saved = f"saved {path} (and registry.md): /assign can use it from now on; commit it with git"
        notes = [ChatItem(kind="note", name="/script", text=saved)]
        if over := scripts.over_cap():
            listed = ", ".join(f"{info.id} ({info.size:,} bytes, last run {when[:10]})" for info, when in over)
            cap = f"the scripts are over the {scripts.MAX_DIR_BYTES:,} byte cap: which should go?"
            notes.append(
                ChatItem(kind="note", name="/script", text=f"{cap} /script delete <id>. Least used first: {listed}")
            )
        self.chat[index + 1 : index + 1] = notes

    @event
    def assign_drop(self, key: str):
        """Esc (or Drop) on a "/assign" proposal: nothing is run or bound."""
        index = self._chat_index(key)
        if index >= 0 and self.chat[index].status == "proposed":
            self.chat[index] = dataclasses.replace(self.chat[index], status="dropped", error="", **_trace_fields([]))

    @event
    def toggle_mention(self, key: str):
        """A mention row's caret: show or fold the text under it."""
        for index, item in enumerate(self.chat):
            if item.kind == "mention" and item.key == key:
                self.chat[index] = dataclasses.replace(item, open=not item.open)

    @event
    def slash_ran(self, name: str, text: str):
        """Add a slash command's row to the chat (kind slash: drawn as a tool call's row)."""
        self.chat.append(ChatItem(kind="slash", name=name, text=text))

    @event
    def clear_chat(self):
        """Start a new conversation: the chat's rows and what the agent remembers of it go. The
        variables it made (r1, ...) stay, as does what was spent. Not while a turn is running.
        """
        if self.busy:
            self.chat.append(ChatItem(kind="note", text="The agent is still working: clear the chat once it is done."))
            return
        session = self._session()
        # results unfolded in the chat are gone with their
        # rows, and the printed mentions' results
        printed = {item.key for item in self.chat_outputs()}
        self.chat, self.streaming = [], ""
        session.ai_history, session.chat_tokens = [], 0
        session.outputs = {key: view for key, view in session.outputs.items() if key not in printed}
        session.ui = {
            slot: ui
            for slot, ui in session.ui.items()
            if not slot.startswith("chat:") and slot.removeprefix("cell:") not in printed
        }
        self._sync_usage()
        self._refresh_debug()

    @rx.event(background=True)
    async def send_chat(self, form: dict[str, Any]):
        prompt = str(form.get("prompt", "")).strip()
        async with self:
            if not prompt or self.busy:
                return
            self.busy = True
            self.streaming = ""
            self.turn_seq += 1
            turn = f"turn-{self.turn_seq}"
            session = self._session()
            self.chat.append(ChatItem(kind="user", text=prompt, key=turn, pieces=mentions.pieces(prompt, session)))
            log_context = self._log_context("chat", turn=turn)
            # "@q1" in the message: the model also gets what the variable holds (mentions.py)
            # built once: a call such as "@q1.sample(5)" gives other rows each time it runs
            block = mentions.context(prompt, session, tool=True)
            sent = "\n\n".join(filter(None, [prompt, block]))
            mentioned = [f"@{mention.path}" for mention in mentions.find(prompt, session)]
            if mentioned:
                # folded: what the AI was given for them
                self.chat.append(
                    ChatItem(
                        kind="mention",
                        name=" ".join(mentioned),
                        text="sent to the AI as they are now",
                        key=f"mention-{len(self.chat)}",
                        detail=block,
                    )
                )

        async def on_delta(delta: str) -> None:
            async with self:
                self.streaming += delta

        with log_context:
            result = await session.ask(prompt, on_delta, sent=sent, toolsets=[mentions.toolset(session)])

        async with self:
            last_table = ""
            for step in result.steps:
                key = f"call-{step.call_id}" if step.call_id else ""
                self.chat.append(ChatItem(kind="step", name=step.tool, text=step.args, key=key))
                if step.result_name:
                    last_table = step.result_name
                    text = f"{step.tool} · {step.result_label}"
                    # some widgets start unfolded in the chat (widgets.py);
                    # _sync below fills their view
                    widget = widget_of(step.result_kind)
                    opened = bool(widget and widget.chat_open)
                    self.chat.append(ChatItem(kind="ref", name=step.result_name, text=text, open=opened))
            if result.text or self.streaming:
                self.chat.append(ChatItem(kind="agent", text=result.text or self.streaming))
            if result.error:
                self.chat.append(ChatItem(kind="error", text=result.error, **_trace_fields(result.trace)))
            if result.usage.requests:
                # the last part ('3 requests') is a link to the debug panel's Requests tab
                *used, requests = result.usage.summary().split(" · ")
                self.chat.append(ChatItem(kind="usage", text=" · ".join(used), name=requests))
            self._sync_usage()
            self.streaming = ""
            self.busy = False
            self._sync(prefer=last_table)
            self._refresh_debug()
